SRC_FILES = {'src/__init__.py': '', 'src/data/__init__.py': '', 'src/data/dataset.py': '"""Data crowd counting Hology 8.0: label titik kepala, dataset PyTorch, dan peta kepadatan target."""\nfrom __future__ import annotations\n\nimport json\nimport os\nfrom pathlib import Path\n\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn.functional as F\nfrom PIL import Image\nfrom torch.utils.data import Dataset\n\nMEAN = np.array([0.485, 0.456, 0.406], dtype=np.float32)\nSTD = np.array([0.229, 0.224, 0.225], dtype=np.float32)\nSTRIDE = 8          # resolusi peta kepadatan = 1/8 gambar\nDENSITY_SCALE = 100.0  # target dikali konstanta agar nilai per piksel tidak terlalu kecil untuk MSE\n\n\ndef find_data_dir(local: str | Path = "../data/raw") -> Path:\n    """Folder yang berisi train/labels dan test/images (di /kaggle/input, ikuti symlink)."""\n    for root, dirs, _ in os.walk("/kaggle/input", followlinks=True):\n        if "train" in dirs and "test" in dirs and (Path(root) / "train" / "labels").exists():\n            return Path(root)\n    return Path(local)\n\n\ndef load_labels(data_dir: str | Path) -> pd.DataFrame:\n    rows = []\n    for f in sorted((Path(data_dir) / "train" / "labels").glob("*.json")):\n        d = json.loads(f.read_text())\n        pts = np.array([[p["x"], p["y"]] for p in d["points"]], dtype=np.float32).reshape(-1, 2)\n        rows.append({"img_id": d["img_id"], "count": int(d["human_num"]), "points": pts})\n    return pd.DataFrame(rows)\n\n\ndef resize_keep(img: Image.Image, pts: np.ndarray | None, max_side: int):\n    """Perkecil gambar agar sisi terpanjang <= max_side (titik ikut diskalakan)."""\n    w, h = img.size\n    s = min(1.0, max_side / max(w, h))\n    if s < 1.0:\n        img = img.resize((max(1, round(w * s)), max(1, round(h * s))), Image.BILINEAR)\n        if pts is not None:\n            pts = pts * s\n    return img, pts\n\n\ndef density_map(pts: np.ndarray, h: int, w: int, sigma: float = 1.0) -> torch.Tensor:\n    """Hitung titik per sel grid 1/STRIDE, lalu haluskan dengan Gaussian. Jumlah total = jumlah orang."""\n    gh, gw = h // STRIDE, w // STRIDE\n    grid = np.zeros((gh, gw), dtype=np.float32)\n    if len(pts):\n        x = np.clip((pts[:, 0] / STRIDE).astype(int), 0, gw - 1)\n        y = np.clip((pts[:, 1] / STRIDE).astype(int), 0, gh - 1)\n        np.add.at(grid, (y, x), 1.0)\n    t = torch.from_numpy(grid)[None, None]\n    r = int(3 * sigma) + 1\n    k = torch.arange(-r, r + 1, dtype=torch.float32)\n    g = torch.exp(-(k ** 2) / (2 * sigma ** 2)); g = g / g.sum()\n    t = F.conv2d(F.pad(t, (r, r, 0, 0), mode="constant"), g.view(1, 1, 1, -1))\n    t = F.conv2d(F.pad(t, (0, 0, r, r), mode="constant"), g.view(1, 1, -1, 1))\n    return t[0]\n\n\ndef to_tensor(img: Image.Image) -> torch.Tensor:\n    a = (np.asarray(img.convert("RGB"), dtype=np.float32) / 255.0 - MEAN) / STD\n    return torch.from_numpy(a.transpose(2, 0, 1).copy())\n\n\nclass CrowdDataset(Dataset):\n    """train=True: skala acak, crop acak, flip. train=False: gambar utuh (di-pad ke kelipatan STRIDE)."""\n\n    def __init__(self, img_dir, ids, points=None, train=False, crop=384, max_side=1024, sigma=1.0, seed=2025):\n        self.img_dir, self.ids, self.points = Path(img_dir), list(ids), points\n        self.train, self.crop, self.max_side, self.sigma = train, crop, max_side, sigma\n        self.rng = np.random.default_rng(seed)\n\n    def __len__(self):\n        return len(self.ids)\n\n    def __getitem__(self, i):\n        img = Image.open(self.img_dir / self.ids[i]).convert("RGB")\n        pts = None if self.points is None else self.points[i].copy()\n        img, pts = resize_keep(img, pts, self.max_side)\n        if not self.train:\n            w, h = img.size\n            x = to_tensor(img)\n            ph, pw = (-h) % STRIDE, (-w) % STRIDE\n            x = F.pad(x, (0, pw, 0, ph))\n            return x, (len(pts) if pts is not None else -1), self.ids[i]\n        s = self.rng.uniform(0.7, 1.3)\n        w, h = img.size\n        nw, nh = max(self.crop, round(w * s)), max(self.crop, round(h * s))\n        sx, sy = nw / w, nh / h\n        img = img.resize((nw, nh), Image.BILINEAR)\n        pts = pts * np.array([sx, sy], dtype=np.float32)\n        x0 = int(self.rng.integers(0, nw - self.crop + 1)); y0 = int(self.rng.integers(0, nh - self.crop + 1))\n        img = img.crop((x0, y0, x0 + self.crop, y0 + self.crop))\n        pts = pts - np.array([x0, y0], dtype=np.float32)\n        pts = pts[(pts[:, 0] >= 0) & (pts[:, 0] < self.crop) & (pts[:, 1] >= 0) & (pts[:, 1] < self.crop)]\n        if self.rng.random() < 0.5:\n            img = img.transpose(Image.FLIP_LEFT_RIGHT)\n            pts[:, 0] = self.crop - 1 - pts[:, 0]\n        return to_tensor(img), density_map(pts, self.crop, self.crop, self.sigma) * DENSITY_SCALE, float(len(pts))\n', 'src/models/__init__.py': '', 'src/models/networks.py': '"""Dua arsitektur pembanding dengan backbone VGG16-BN pra-latih (stride 8).\n\n- CountRegressor: fitur -> global average pooling -> MLP -> satu angka (jumlah orang).\n- CSRNet: fitur -> konvolusi dilasi -> peta kepadatan 1/8; jumlah orang = jumlah seluruh piksel peta.\n"""\nfrom __future__ import annotations\n\nimport torch\nimport torch.nn as nn\nfrom torchvision.models import VGG16_BN_Weights, vgg16_bn\n\n\ndef vgg_frontend(pretrained: bool = True) -> nn.Sequential:\n    vgg = vgg16_bn(weights=VGG16_BN_Weights.IMAGENET1K_V1 if pretrained else None)\n    return nn.Sequential(*list(vgg.features.children())[:33])  # sampai conv4_3 + BN + ReLU, stride 8, 512 kanal\n\n\nclass CSRNet(nn.Module):\n    def __init__(self, pretrained: bool = True):\n        super().__init__()\n        self.frontend = vgg_frontend(pretrained)\n        layers, c_in = [], 512\n        for c in (512, 512, 512, 256, 128, 64):\n            layers += [nn.Conv2d(c_in, c, 3, padding=2, dilation=2), nn.ReLU(inplace=True)]\n            c_in = c\n        self.backend = nn.Sequential(*layers)\n        self.head = nn.Conv2d(64, 1, 1)\n        for m in list(self.backend.modules()) + [self.head]:\n            if isinstance(m, nn.Conv2d):\n                nn.init.normal_(m.weight, std=0.01); nn.init.zeros_(m.bias)\n\n    def forward(self, x):\n        return torch.relu(self.head(self.backend(self.frontend(x))))\n\n\nclass CountRegressor(nn.Module):\n    def __init__(self, pretrained: bool = True):\n        super().__init__()\n        self.frontend = vgg_frontend(pretrained)\n        self.head = nn.Sequential(nn.AdaptiveAvgPool2d(1), nn.Flatten(), nn.Linear(512, 256), nn.ReLU(inplace=True), nn.Linear(256, 1))\n\n    def forward(self, x):\n        # memprediksi log(1 + jumlah) agar rentang 1..3000 stabil untuk dilatih\n        return self.head(self.frontend(x)).squeeze(1)\n', 'src/models/train.py': '"""Loop training, evaluasi, dan prediksi untuk CSRNet dan CountRegressor."""\nfrom __future__ import annotations\n\nimport time\n\nimport numpy as np\nimport torch\nimport torch.nn.functional as F\n\nfrom src.data.dataset import DENSITY_SCALE\n\n\ndef set_seed(seed: int = 2025):\n    import random\n    random.seed(seed); np.random.seed(seed); torch.manual_seed(seed); torch.cuda.manual_seed_all(seed)\n    torch.backends.cudnn.benchmark = True\n\n\n@torch.no_grad()\ndef predict_counts(model, loader, device, kind: str = "density", tta: bool = False):\n    """Prediksi jumlah untuk setiap gambar (batch size 1, gambar utuh)."""\n    model.eval()\n    ids, preds, trues, maps = [], [], [], {}\n    for x, y, img_id in loader:\n        x = x.to(device)\n        with torch.autocast(device_type=device.type, enabled=device.type == "cuda"):\n            out = model(x)\n            if tta:\n                out2 = model(torch.flip(x, dims=[3]))\n        if kind == "density":\n            c = out.float().sum().item() / DENSITY_SCALE\n            if tta:\n                c = (c + out2.float().sum().item() / DENSITY_SCALE) / 2\n            maps[img_id[0]] = out[0, 0].float().cpu().numpy() / DENSITY_SCALE\n        else:\n            c = float(np.expm1(out.float().item()))\n            if tta:\n                c = (c + float(np.expm1(out2.float().item()))) / 2\n        ids.append(img_id[0]); preds.append(max(c, 0.0)); trues.append(float(y[0]))\n    return np.array(ids), np.array(preds), np.array(trues), maps\n\n\ndef train_model(model, train_loader, val_loader, device, epochs: int, lr: float = 1e-4, kind: str = "density",\n                eval_every: int = 2, log=print):\n    """Adam + cosine LR. Simpan bobot dengan MAE validasi terbaik."""\n    model.to(device)\n    opt = torch.optim.Adam(model.parameters(), lr=lr, weight_decay=1e-4)\n    sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=epochs)\n    scaler = torch.amp.GradScaler(enabled=device.type == "cuda")\n    hist, best, best_state = [], np.inf, None\n    for ep in range(1, epochs + 1):\n        model.train(); t0 = time.time(); losses = []\n        for x, dens, cnt in train_loader:\n            x, dens, cnt = x.to(device), dens.to(device), cnt.to(device).float()\n            with torch.autocast(device_type=device.type, enabled=device.type == "cuda"):\n                out = model(x)\n                if kind == "density":\n                    loss = F.mse_loss(out.float(), dens, reduction="sum") / x.size(0)\n                else:\n                    loss = F.l1_loss(out.float(), torch.log1p(cnt))\n            opt.zero_grad(set_to_none=True)\n            scaler.scale(loss).backward(); scaler.step(opt); scaler.update()\n            losses.append(loss.item())\n        sched.step()\n        row = {"epoch": ep, "loss": float(np.mean(losses)), "detik": time.time() - t0}\n        if ep % eval_every == 0 or ep == epochs:\n            _, p, t, _ = predict_counts(model, val_loader, device, kind)\n            row["val_mae"] = float(np.mean(np.abs(p - t)))\n            if row["val_mae"] < best:\n                best = row["val_mae"]; best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}\n            log(f"epoch {ep:3d} | loss {row[\'loss\']:.4f} | MAE val {row[\'val_mae\']:.2f} | {row[\'detik\']:.0f}s")\n        hist.append(row)\n    model.load_state_dict(best_state)\n    return model, hist, best\n', 'src/visualization/__init__.py': '', 'src/visualization/plots.py': '"""Gaya grafik yang konsisten dan ramah buta warna (palet Okabe–Ito)."""\nfrom __future__ import annotations\n\nfrom pathlib import Path\n\nimport matplotlib.pyplot as plt\nimport matplotlib.ticker as mtick\nimport seaborn as sns\n\nPALETTE = {"normal": "#0072B2", "fraud": "#D55E00", "accent": "#009E73", "neutral": "#8C8C8C"}\n\n\ndef set_style() -> None:\n    sns.set_theme(style="whitegrid", context="notebook", palette="colorblind")\n    plt.rcParams.update({"figure.dpi": 110, "axes.titleweight": "bold", "axes.titlesize": 12})\n\n\ndef save_fig(fig_dir: Path, name: str) -> None:\n    """Rapikan layout, simpan PNG ke `fig_dir`, lalu tampilkan."""\n    plt.tight_layout()\n    plt.savefig(Path(fig_dir) / f"{name}.png", dpi=130, bbox_inches="tight")\n    plt.show()\n\n\ndef pct_axis(ax, decimals: int = 1, axis: str = "y") -> None:\n    fmt = mtick.PercentFormatter(1, decimals=decimals)\n    (ax.yaxis if axis == "y" else ax.xaxis).set_major_formatter(fmt)\n\n\ndef ref_line(ax, value: float, label: str = "rata-rata") -> None:\n    ax.axhline(value, color=PALETTE["neutral"], ls="--", lw=1.2, label=label)\n'}
NOTEBOOK = json.loads('{\n "cells": [\n  {\n   "cell_type": "markdown",\n   "id": "187e71f4",\n   "metadata": {},\n   "source": [\n    "# Menghitung Kerumunan dari Satu Foto: Peta Kepadatan vs Regresi Langsung\\n",\n    "\\n",\n    "| | |\\n",\n    "| --- | --- |\\n",\n    "| **Kompetisi** | [Penyisihan Hology 8.0 2025 Data Mining](https://www.kaggle.com/competitions/penyisihan-hology-8-0-2025-data-mining) (Universitas Brawijaya, Kaggle, September 2025) |\\n",\n    "| **Tujuan** | Memprediksi jumlah orang dalam setiap gambar kerumunan (metrik MAE) |\\n",\n    "| **Data** | 1.900 gambar latih dengan koordinat kepala setiap orang, 500 gambar uji |\\n",\n    "| **Penulis** | Fauzan Ahsanudin Alfikri · [Kaggle: fauzan2](https://www.kaggle.com/fauzan2) |\\n",\n    "| **Tanggal** | Disusun ulang November 2026 (notebook asli 2025 hilang) |\\n",\n    "| **Lingkungan** | Dijalankan penuh di Kaggle (GPU), ±1 jam |\\n",\n    "\\n",\n    "**Pertanyaan penelitian.** Jumlah orang dalam satu gambar berkisar dari 1 sampai lebih dari 3.000. Apakah lebih baik\\n",\n    "model langsung menebak satu angka, atau belajar \\"di mana\\" setiap orang berada lalu menjumlahkannya?\\n",\n    "\\n",\n    "**Ringkasan temuan.**\\n",\n    "- Jumlah orang per gambar sangat timpang: median 28, tetapi rata-rata 139 dan maksimum 3.139. 10% gambar terpadat memuat 58% seluruh orang, sehingga MAE ditentukan oleh sedikit gambar yang sangat padat.\\n",\n    "- Skala kepala berubah drastis: jarak antar kepala 11–75 px (persentil 10–90) dan makin rapat pada gambar yang makin padat (Spearman −0,80). Model harus mengenali orang pada berbagai ukuran.\\n",\n    "- Regresi jumlah langsung (VGG16-BN → satu angka) tidak stabil dan berakhir di MAE validasi 139,4, lebih buruk dari menebak median (128,0).\\n",\n    "- Peta kepadatan CSRNet yang belajar dari setiap titik kepala mencapai **MAE validasi 24,9** dengan error relatif median 16%. 79% error absolut berasal dari gambar berisi lebih dari 200 orang.\\n",\n    "- Late submission: public **24,45**, private **21,75**, jauh lebih baik daripada submission tim saat kompetisi (private terbaik 39,44, peringkat akhir 60 dari 77), tetapi masih di atas peringkat 1 (12,04).\\n",\n    "\\n",\n    "**Alur:** 1. Setup → 2. Memahami data → 3. EDA → 4. Preprocessing & target → 5. Desain validasi → 6. Baseline →\\n",\n    "7. Regresi jumlah langsung → 8. Peta kepadatan (CSRNet) → 9. Evaluasi → 10. Submission → 11. Kesimpulan"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a9ce272b",\n   "metadata": {},\n   "source": [\n    "## 1. Setup\\n",\n    "\\n",\n    "Semua import, parameter, dan path ada di sel ini. Dataset dan pembentukan peta kepadatan ada di `src/data`, arsitektur di\\n",\n    "`src/models/networks.py`, dan loop training di `src/models/train.py`. Jika GPU tidak tersedia, notebook berjalan dalam\\n",\n    "mode uji kecil (subset data, satu epoch) agar alurnya tetap bisa diperiksa."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2c1afac0",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import os\\n",\n    "import shutil\\n",\n    "import sys\\n",\n    "import time\\n",\n    "import warnings\\n",\n    "from importlib.metadata import version\\n",\n    "from pathlib import Path\\n",\n    "\\n",\n    "import numpy as np\\n",\n    "import pandas as pd\\n",\n    "import matplotlib.pyplot as plt\\n",\n    "import seaborn as sns\\n",\n    "import torch\\n",\n    "from PIL import Image\\n",\n    "from scipy.spatial import cKDTree\\n",\n    "from torch.utils.data import DataLoader\\n",\n    "\\n",\n    "SRC_ROOT = Path.cwd().parent\\n",\n    "for r, _, f in os.walk(\\"/kaggle/input\\", followlinks=True):\\n",\n    "    if Path(r).name == \\"models\\" and \\"networks.py\\" in f:\\n",\n    "        pkg = Path(r).parent\\n",\n    "        if pkg.name == \\"src\\":\\n",\n    "            SRC_ROOT = pkg.parent\\n",\n    "        else:\\n",\n    "            SRC_ROOT = Path(\\"/tmp/project\\")\\n",\n    "            shutil.copytree(pkg, SRC_ROOT / \\"src\\", dirs_exist_ok=True)\\n",\n    "        break\\n",\n    "sys.path.insert(0, str(SRC_ROOT))\\n",\n    "from src.data.dataset import STRIDE, CrowdDataset, density_map, find_data_dir, load_labels, resize_keep\\n",\n    "from src.models.networks import CSRNet, CountRegressor\\n",\n    "from src.models.train import predict_counts, set_seed, train_model\\n",\n    "from src.visualization.plots import PALETTE, pct_axis, save_fig, set_style\\n",\n    "\\n",\n    "# ── Parameter eksperimen\\n",\n    "SEED = 2025\\n",\n    "DEVICE = torch.device(\\"cuda\\" if torch.cuda.is_available() else \\"cpu\\")\\n",\n    "SMOKE = DEVICE.type != \\"cuda\\"          # tanpa GPU: uji alur dengan subset kecil\\n",\n    "VAL_FRAC = 0.2\\n",\n    "CROP = 128 if SMOKE else 384\\n",\n    "MAX_SIDE = 384 if SMOKE else 1024     # sisi terpanjang gambar setelah resize\\n",\n    "BATCH = 8\\n",\n    "EPOCHS_REG = 1 if SMOKE else 25\\n",\n    "EPOCHS_DENSITY = 1 if SMOKE else 70\\n",\n    "LR = 1e-4\\n",\n    "SIGMA = 1.0                            # lebar Gaussian dalam sel peta kepadatan (1 sel = 8 piksel)\\n",\n    "\\n",\n    "DATA_DIR = find_data_dir(local=\\"../data/raw\\")\\n",\n    "OUT_DIR = Path(\\"/kaggle/working\\") if Path(\\"/kaggle/working\\").exists() else Path(\\"../reports\\")\\n",\n    "FIG_DIR = OUT_DIR / \\"figures\\"\\n",\n    "FIG_DIR.mkdir(parents=True, exist_ok=True)\\n",\n    "\\n",\n    "warnings.filterwarnings(\\"ignore\\")\\n",\n    "set_style()\\n",\n    "set_seed(SEED)\\n",\n    "C1, C2, C3, CN = PALETTE[\\"normal\\"], PALETTE[\\"fraud\\"], PALETTE[\\"accent\\"], PALETTE[\\"neutral\\"]\\n",\n    "T0 = time.time()\\n",\n    "print(\\"DATA_DIR:\\", DATA_DIR, \\"| DEVICE:\\", DEVICE, torch.cuda.get_device_name(0) if DEVICE.type == \\"cuda\\" else \\"\\", \\"| SMOKE:\\", SMOKE)"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a9a1308f",\n   "metadata": {},\n   "source": [\n    "## 2. Memahami data\\n",\n    "\\n",\n    "Setiap gambar latih punya file JSON berisi `human_num` (jumlah orang) dan `points`, yaitu koordinat kepala setiap orang.\\n",\n    "Label titik ini lebih kaya daripada sekadar angka: model bisa belajar lokasi orang, bukan hanya jumlahnya."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "1329dd13",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "labels = load_labels(DATA_DIR)\\n",\n    "sizes = [Image.open(DATA_DIR / \\"train\\" / \\"images\\" / i).size for i in labels.img_id]\\n",\n    "labels[\\"w\\"], labels[\\"h\\"] = [s[0] for s in sizes], [s[1] for s in sizes]\\n",\n    "test_ids = sorted(os.listdir(DATA_DIR / \\"test\\" / \\"images\\"), key=lambda s: int(Path(s).stem))\\n",\n    "sample = pd.read_csv(DATA_DIR / \\"sample_submission.csv\\")\\n",\n    "assert (labels[\\"count\\"] == labels.points.apply(len)).all()\\n",\n    "print(f\\"Train: {len(labels):,} gambar, {labels[\'count\'].sum():,} orang | Test: {len(test_ids)} gambar\\")\\n",\n    "labels[[\\"count\\", \\"w\\", \\"h\\"]].describe(percentiles=[0.1, 0.25, 0.5, 0.75, 0.9, 0.99]).T.style.format(\\"{:,.1f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a1e32fd2",\n   "metadata": {},\n   "source": [\n    "## 3. Exploratory Data Analysis\\n",\n    "\\n",\n    "### 3.1 Seberapa beragam jumlah orang per gambar?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "964476e7",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "c = labels[\\"count\\"].values\\n",\n    "srt = np.sort(c)[::-1]\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.5))\\n",\n    "ax[0].hist(c, bins=np.logspace(0, np.log10(c.max() + 1), 40), color=C1)\\n",\n    "ax[0].set_xscale(\\"log\\"); ax[0].set(xlabel=\\"jumlah orang (skala log)\\", ylabel=\\"gambar\\", title=\\"Distribusi jumlah orang per gambar\\")\\n",\n    "ax[0].axvline(np.median(c), color=C2, ls=\\"--\\", label=f\\"median {np.median(c):.0f}\\"); ax[0].axvline(c.mean(), color=CN, ls=\\":\\", label=f\\"rata-rata {c.mean():.0f}\\"); ax[0].legend()\\n",\n    "ax[1].plot(np.arange(1, len(c) + 1) / len(c), np.cumsum(srt) / srt.sum(), color=C2)\\n",\n    "pct_axis(ax[1], 0); ax[1].xaxis.set_major_formatter(plt.matplotlib.ticker.PercentFormatter(1, 0))\\n",\n    "ax[1].set(xlabel=\\"gambar terpadat (persentil)\\", ylabel=\\"porsi seluruh orang\\", title=\\"Seberapa terkonsentrasi orang di gambar terpadat?\\")\\n",\n    "save_fig(FIG_DIR, \\"01_count_distribution\\")\\n",\n    "top10 = srt[: len(c) // 10].sum() / srt.sum()\\n",\n    "print(f\\"10% gambar terpadat memuat {top10:.0%} dari seluruh orang; {np.mean(c <= 50):.0%} gambar berisi ≤ 50 orang\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "7e5b65a5",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Distribusinya sangat miring: 59% gambar berisi paling banyak 50 orang, sedangkan 10% gambar terpadat memuat 58% seluruh orang. Untuk MAE, artinya beberapa ratus gambar padat menentukan hampir seluruh skor, sementara gambar sepi hampir tidak berpengaruh."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e0f2dcb9",\n   "metadata": {},\n   "source": [\n    "### 3.2 Seperti apa gambarnya?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "3920f5f1",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "picks = [labels.iloc[(labels[\\"count\\"] - q).abs().argsort().iloc[0]] for q in [5, 40, 300, 1500]]\\n",\n    "fig, axes = plt.subplots(1, 4, figsize=(20, 4.6))\\n",\n    "for ax, row in zip(axes, picks):\\n",\n    "    img = Image.open(DATA_DIR / \\"train\\" / \\"images\\" / row.img_id)\\n",\n    "    ax.imshow(img); ax.scatter(row.points[:, 0], row.points[:, 1], s=4, c=C2)\\n",\n    "    ax.set_title(f\\"{row.img_id}: {row[\'count\']} orang ({img.size[0]}×{img.size[1]})\\", fontsize=10); ax.axis(\\"off\\")\\n",\n    "save_fig(FIG_DIR, \\"02_examples\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "6acf60bd",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Gambar berasal dari sumber yang sangat berbeda: kamera CCTV di halte dengan belasan orang, foto konser close-up, dan foto lapangan dengan ribuan kepala kecil di kejauhan. Pada gambar padat, kepala di bagian belakang hanya berupa titik beberapa piksel."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "c5aad037",\n   "metadata": {},\n   "source": [\n    "### 3.3 Ukuran kepala: seberapa besar variasi skala?\\n",\n    "\\n",\n    "Jarak ke tetangga terdekat antar kepala adalah proksi ukuran kepala dalam piksel. Jika jarak ini sangat bervariasi, model\\n",\n    "harus mengenali orang pada berbagai skala."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "5dca6c07",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "nn_med = []\\n",\n    "for pts in labels.points:\\n",\n    "    if len(pts) >= 2:\\n",\n    "        d, _ = cKDTree(pts).query(pts, k=2)\\n",\n    "        nn_med.append(np.median(d[:, 1]))\\n",\n    "    else:\\n",\n    "        nn_med.append(np.nan)\\n",\n    "labels[\\"nn_px\\"] = nn_med\\n",\n    "labels[\\"nn_rel\\"] = labels.nn_px / np.maximum(labels.w, labels.h)\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.5))\\n",\n    "ax[0].scatter(labels[\\"count\\"], labels.nn_px, s=6, alpha=0.4, color=C1)\\n",\n    "ax[0].set(xscale=\\"log\\", yscale=\\"log\\", xlabel=\\"jumlah orang\\", ylabel=\\"median jarak antar kepala (px)\\", title=\\"Semakin padat, semakin kecil kepala\\")\\n",\n    "ax[1].scatter(labels.w * labels.h / 1e6, labels[\\"count\\"], s=6, alpha=0.4, color=C1)\\n",\n    "ax[1].set(xscale=\\"log\\", yscale=\\"log\\", xlabel=\\"luas gambar (megapiksel)\\", ylabel=\\"jumlah orang\\", title=\\"Resolusi gambar vs jumlah orang\\")\\n",\n    "save_fig(FIG_DIR, \\"03_scale\\")\\n",\n    "rho = labels[[\\"count\\", \\"nn_px\\"]].corr(\\"spearman\\").iloc[0, 1]\\n",\n    "area_rho = pd.Series(labels.w * labels.h).corr(labels[\\"count\\"], method=\\"spearman\\")\\n",\n    "print(f\\"Spearman jumlah vs jarak antar kepala: {rho:.2f} | jumlah vs luas gambar: {area_rho:.2f}\\")\\n",\n    "print(\\"Jarak antar kepala (px), persentil 10/50/90:\\", np.nanpercentile(labels.nn_px, [10, 50, 90]).round(1))"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "94f12cc5",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Jarak ke kepala terdekat (proksi ukuran kepala) berkisar 11 px di persentil 10 sampai 75 px di persentil 90, dengan median 31 px. Makin padat gambarnya, makin kecil kepalanya (Spearman jumlah vs jarak −0,80). Gambar yang lebih besar juga cenderung lebih padat (Spearman 0,60), jadi memperkecil gambar terlalu banyak akan menghapus orang di gambar terpadat. Ini alasan sisi terpanjang dibatasi 1024 px dan augmentasi skala dipakai."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "06df8c8c",\n   "metadata": {},\n   "source": [\n    "### 3.4 Di bagian mana orang biasanya berada?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2b2fe5ff",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "H = np.zeros((50, 50))\\n",\n    "for pts, w, h in zip(labels.points, labels.w, labels.h):\\n",\n    "    if len(pts):\\n",\n    "        hx, _, _ = np.histogram2d(np.clip(pts[:, 1] / h, 0, 0.999), np.clip(pts[:, 0] / w, 0, 0.999), bins=50, range=[[0, 1], [0, 1]])\\n",\n    "        H += hx / len(pts)\\n",\n    "fig, ax = plt.subplots(figsize=(6, 5))\\n",\n    "im = ax.imshow(H / H.sum(), cmap=\\"cividis\\", extent=[0, 1, 1, 0])\\n",\n    "ax.set(xlabel=\\"posisi horizontal (relatif)\\", ylabel=\\"posisi vertikal (relatif)\\", title=\\"Sebaran posisi kepala (rata-rata per gambar)\\")\\n",\n    "plt.colorbar(im, ax=ax, label=\\"porsi\\")\\n",\n    "save_fig(FIG_DIR, \\"04_spatial\\")\\n",\n    "upper = H[:25].sum() / H.sum()\\n",\n    "print(f\\"Porsi kepala di setengah atas gambar: {upper:.0%}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "9ea45525",\n   "metadata": {},\n   "source": [\n    "**Temuan.** 79% kepala berada di setengah atas gambar, karena kerumunan difoto dari depan atau atas dan orang yang lebih jauh tampak lebih tinggi di bingkai. Kepala yang paling kecil dan paling rapat ada di bagian atas, tepat di tempat model paling mudah salah hitung."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "2236c5bd",\n   "metadata": {},\n   "source": [\n    "## 4. Preprocessing dan target\\n",\n    "\\n",\n    "| Temuan EDA | Keputusan |\\n",\n    "| --- | --- |\\n",\n    "| Gambar sampai 1920×1080, kepala bisa sekecil beberapa piksel (3.3) | sisi terpanjang dibatasi 1024 px agar muat di GPU tanpa membuang terlalu banyak detail |\\n",\n    "| Jumlah orang dari 1 sampai 3.000+, distribusi sangat miring (3.1) | regresi langsung memprediksi log(1 + jumlah); peta kepadatan tidak perlu transformasi |\\n",\n    "| Variasi skala kepala besar (3.3) | augmentasi skala acak 0,7–1,3×, crop acak 384 px, flip horizontal |\\n",\n    "| Label berupa titik kepala | target peta kepadatan: titik dihitung per sel 8×8 px lalu dihaluskan Gaussian; jumlah seluruh peta = jumlah orang |"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "01083dee",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "row = picks[2]\\n",\n    "img, pts = resize_keep(Image.open(DATA_DIR / \\"train\\" / \\"images\\" / row.img_id), row.points, MAX_SIDE)\\n",\n    "w, h = img.size\\n",\n    "dm = density_map(pts, h - h % STRIDE, w - w % STRIDE, SIGMA)[0].numpy()\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(14, 4.6))\\n",\n    "ax[0].imshow(img); ax[0].scatter(pts[:, 0], pts[:, 1], s=4, c=C2); ax[0].set_title(f\\"Titik kepala: {len(pts)} orang\\"); ax[0].axis(\\"off\\")\\n",\n    "ax[1].imshow(dm, cmap=\\"cividis\\"); ax[1].set_title(f\\"Peta kepadatan target 1/8 resolusi (jumlah = {dm.sum():.1f})\\"); ax[1].axis(\\"off\\")\\n",\n    "save_fig(FIG_DIR, \\"05_density_target\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1552aef0",\n   "metadata": {},\n   "source": [\n    "## 5. Desain validasi\\n",\n    "\\n",\n    "20% gambar latih disisihkan sebagai validasi, dibagi secara stratified berdasarkan kelompok jumlah orang agar gambar sangat\\n",\n    "padat ada di kedua bagian. Semua model dibandingkan pada validasi yang sama. Model akhir untuk data uji adalah bobot dengan\\n",\n    "MAE validasi terbaik."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "800cdba6",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "rng = np.random.default_rng(SEED)\\n",\n    "bins = pd.qcut(labels[\\"count\\"].rank(method=\\"first\\"), 10, labels=False)\\n",\n    "val_mask = np.zeros(len(labels), bool)\\n",\n    "for b in range(10):\\n",\n    "    idx = np.where(bins == b)[0]\\n",\n    "    val_mask[rng.choice(idx, int(round(len(idx) * VAL_FRAC)), replace=False)] = True\\n",\n    "tr_df, va_df = labels[~val_mask].reset_index(drop=True), labels[val_mask].reset_index(drop=True)\\n",\n    "if SMOKE:\\n",\n    "    tr_df, va_df = tr_df.sample(40, random_state=SEED).reset_index(drop=True), va_df.sample(20, random_state=SEED).reset_index(drop=True)\\n",\n    "IMG_TR = DATA_DIR / \\"train\\" / \\"images\\"\\n",\n    "ds_tr = CrowdDataset(IMG_TR, tr_df.img_id, list(tr_df.points), train=True, crop=CROP, max_side=MAX_SIDE, sigma=SIGMA, seed=SEED)\\n",\n    "ds_va = CrowdDataset(IMG_TR, va_df.img_id, list(va_df.points), train=False, max_side=MAX_SIDE)\\n",\n    "g = torch.Generator().manual_seed(SEED)\\n",\n    "dl_tr = DataLoader(ds_tr, batch_size=BATCH, shuffle=True, num_workers=2, drop_last=True, generator=g)\\n",\n    "dl_va = DataLoader(ds_va, batch_size=1, shuffle=False, num_workers=2)\\n",\n    "pd.DataFrame({\\"gambar\\": [len(tr_df), len(va_df)], \\"median jumlah\\": [tr_df[\\"count\\"].median(), va_df[\\"count\\"].median()],\\n",\n    "              \\"rata-rata jumlah\\": [tr_df[\\"count\\"].mean(), va_df[\\"count\\"].mean()], \\"maks\\": [tr_df[\\"count\\"].max(), va_df[\\"count\\"].max()]},\\n",\n    "             index=[\\"latih\\", \\"validasi\\"]).style.format(\\"{:,.1f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "461b3eed",\n   "metadata": {},\n   "source": [\n    "## 6. Baseline\\n",\n    "\\n",\n    "Menebak angka yang sama untuk semua gambar. Untuk MAE, konstanta terbaik adalah **median** jumlah orang di data latih."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "82b92eb5",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "yv = va_df[\\"count\\"].values.astype(float)\\n",\n    "RESULTS = {\\n",\n    "    \\"konstanta: rata-rata\\": np.full(len(yv), tr_df[\\"count\\"].mean()),\\n",\n    "    \\"konstanta: median\\": np.full(len(yv), tr_df[\\"count\\"].median()),\\n",\n    "}\\n",\n    "pd.Series({k: np.mean(np.abs(p - yv)) for k, p in RESULTS.items()}).to_frame(\\"MAE validasi\\").style.format(\\"{:.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e779c2d2",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Konstanta median (28 orang) memberi MAE 128,0, lebih baik daripada rata-rata (160,4), karena MAE menghukum selisih absolut dan median meminimalkannya. Error relatif median 89% menunjukkan bahwa satu angka tidak bisa mewakili gambar sepi dan gambar padat sekaligus."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "779a0d5d",\n   "metadata": {},\n   "source": [\n    "## 7. Regresi jumlah langsung\\n",\n    "\\n",\n    "Backbone VGG16-BN pra-latih ImageNet, global average pooling, lalu MLP yang memprediksi log(1 + jumlah). Model ini hanya\\n",\n    "diberi tahu \\"berapa\\", tanpa informasi lokasi. Karena crop latih hanya memuat sebagian gambar, targetnya adalah jumlah orang\\n",\n    "di dalam crop."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "6cca4ce9",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "set_seed(SEED)\\n",\n    "t = time.time()\\n",\n    "reg, hist_reg, _ = train_model(CountRegressor(pretrained=not SMOKE), dl_tr, dl_va, DEVICE, EPOCHS_REG, LR, kind=\\"regression\\", eval_every=1 if SMOKE else 5)\\n",\n    "_, p_reg, _, _ = predict_counts(reg, dl_va, DEVICE, \\"regression\\")\\n",\n    "RESULTS[\\"regresi jumlah langsung\\"] = p_reg\\n",\n    "print(f\\"Regresi: {(time.time() - t) / 60:.1f} menit | MAE validasi {np.mean(np.abs(p_reg - yv)):.2f}\\")\\n",\n    "del reg; torch.cuda.empty_cache()"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "d97c8a55",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Regresi langsung sangat tidak stabil: MAE validasi melompat dari 139 ke 1.257 lalu kembali ke 142 dalam beberapa epoch. Bobot terbaiknya (epoch 5, MAE 139,4) bahkan kalah dari konstanta median. Grafik prediksi vs aktual di bagian 9 memperlihatkan sebabnya: model sistematis meremehkan gambar padat. Model dilatih pada crop 384 px, tetapi diuji pada gambar utuh, dan satu angka per gambar terlalu sedikit sinyal untuk belajar menghitung ribuan orang."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "2433b4d5",\n   "metadata": {},\n   "source": [\n    "## 8. Peta kepadatan: CSRNet\\n",\n    "\\n",\n    "Arsitektur CSRNet (Li dkk., 2018): 10 lapis konvolusi pertama VGG16-BN pra-latih, lalu 6 lapis konvolusi dilasi yang\\n",\n    "memperluas *receptive field* tanpa mengecilkan resolusi. Keluarannya peta kepadatan 1/8 resolusi gambar, dan jumlah orang\\n",\n    "adalah jumlah seluruh nilainya. Model belajar dari setiap titik kepala, sehingga satu gambar memberi ratusan sinyal latih,\\n",\n    "bukan satu angka."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "8be7d7ec",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "set_seed(SEED)\\n",\n    "t = time.time()\\n",\n    "csr, hist_csr, best_csr = train_model(CSRNet(pretrained=not SMOKE), dl_tr, dl_va, DEVICE, EPOCHS_DENSITY, LR, kind=\\"density\\", eval_every=1 if SMOKE else 2)\\n",\n    "ids_va, p_csr, _, maps_va = predict_counts(csr, dl_va, DEVICE, \\"density\\")\\n",\n    "_, p_csr_tta, _, _ = predict_counts(csr, dl_va, DEVICE, \\"density\\", tta=True)\\n",\n    "RESULTS[\\"CSRNet peta kepadatan\\"] = p_csr\\n",\n    "RESULTS[\\"CSRNet + flip TTA\\"] = p_csr_tta\\n",\n    "TRAIN_MIN = (time.time() - t) / 60\\n",\n    "print(f\\"CSRNet: {TRAIN_MIN:.1f} menit | MAE validasi terbaik {best_csr:.2f}\\")"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "c6e9b132",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "hc = pd.DataFrame(hist_csr); hr = pd.DataFrame(hist_reg)\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 4.3))\\n",\n    "ax[0].plot(hc.epoch, hc.loss, color=C2); ax[0].set(xlabel=\\"epoch\\", ylabel=\\"loss MSE peta kepadatan\\", title=\\"CSRNet: loss latih\\")\\n",\n    "ax[1].plot(hc.dropna().epoch, hc.dropna().val_mae, marker=\\"o\\", ms=3, color=C2, label=\\"CSRNet\\")\\n",\n    "ax[1].plot(hr.dropna().epoch, hr.dropna().val_mae, marker=\\"s\\", ms=3, color=C1, label=\\"regresi langsung\\")\\n",\n    "ax[1].axhline(np.mean(np.abs(RESULTS[\\"konstanta: median\\"] - yv)), color=CN, ls=\\"--\\", label=\\"konstanta median\\")\\n",\n    "ax[1].set(xlabel=\\"epoch\\", ylabel=\\"MAE validasi\\", title=\\"MAE validasi selama training\\", yscale=\\"log\\"); ax[1].legend()\\n",\n    "save_fig(FIG_DIR, \\"06_training_curves\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "a644f2a0",\n   "metadata": {},\n   "source": [\n    "**Temuan.** CSRNet sudah jauh di bawah konstanta median pada epoch 4 (MAE 98,6) dan turun di bawah MAE 40 setelah epoch 14. MAE validasi tetap berfluktuasi antara 25 dan 45 karena beberapa gambar sangat padat di validasi mendominasi skor, tetapi loss latih turun stabil. Bobot terbaik ada di epoch 42 (MAE 24,9)."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "58287c49",\n   "metadata": {},\n   "source": [\n    "## 9. Evaluasi\\n",\n    "\\n",\n    "### 9.1 Perbandingan model"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "2d6e72ea",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "res = pd.DataFrame({k: {\\"MAE\\": np.mean(np.abs(p - yv)), \\"RMSE\\": np.sqrt(np.mean((p - yv) ** 2)),\\n",\n    "                        \\"median error relatif\\": np.median(np.abs(p - yv) / yv)} for k, p in RESULTS.items()}).T.sort_values(\\"MAE\\")\\n",\n    "FINAL_NAME = [k for k in res.index if k.startswith(\\"CSRNet\\")][0]   # varian CSRNet terbaik dipakai untuk submission\\n",\n    "res.style.format({\\"MAE\\": \\"{:.2f}\\", \\"RMSE\\": \\"{:.2f}\\", \\"median error relatif\\": \\"{:.1%}\\"}).highlight_min(subset=[\\"MAE\\"], color=\\"#CDE7F0\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "e365d5eb",\n   "metadata": {},\n   "source": [\n    "**Temuan.** CSRNet menurunkan MAE dari 128,0 (konstanta median) menjadi **24,9**, sekitar 5 kali lebih kecil, dan 5,6 kali lebih baik dari regresi langsung (139,4). Error relatif median turun dari 59% (regresi) menjadi 16%. Flip horizontal saat inferensi (TTA) tidak membantu (25,1), sehingga model akhir memakai prediksi tanpa TTA."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "f168f5a5",\n   "metadata": {},\n   "source": [\n    "### 9.2 Di mana error terjadi?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "68c7799c",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "p_fin = RESULTS[FINAL_NAME]\\n",\n    "grp = pd.cut(yv, [0, 10, 50, 200, 1000, np.inf], labels=[\\"1–10\\", \\"11–50\\", \\"51–200\\", \\"201–1000\\", \\">1000\\"])\\n",\n    "err = pd.DataFrame({\\"kelompok\\": grp, \\"abs\\": np.abs(p_fin - yv), \\"rel\\": np.abs(p_fin - yv) / yv, \\"reg\\": np.abs(RESULTS[\\"regresi jumlah langsung\\"] - yv)})\\n",\n    "by = err.groupby(\\"kelompok\\", observed=True).agg(gambar=(\\"abs\\", \\"size\\"), MAE=(\\"abs\\", \\"mean\\"), MAE_regresi=(\\"reg\\", \\"mean\\"), error_relatif=(\\"rel\\", \\"median\\"), total_error=(\\"abs\\", \\"sum\\"))\\n",\n    "by[\\"porsi total error\\"] = by.total_error / by.total_error.sum()\\n",\n    "fig, ax = plt.subplots(1, 2, figsize=(15, 5))\\n",\n    "lim = [1, yv.max() * 1.3]\\n",\n    "ax[0].scatter(yv, np.maximum(RESULTS[\\"regresi jumlah langsung\\"], 0.5), s=10, alpha=0.5, color=C1, label=\\"regresi langsung\\")\\n",\n    "ax[0].scatter(yv, np.maximum(p_fin, 0.5), s=10, alpha=0.6, color=C2, label=FINAL_NAME)\\n",\n    "ax[0].plot(lim, lim, color=\\"black\\", lw=0.8); ax[0].set(xscale=\\"log\\", yscale=\\"log\\", xlabel=\\"jumlah aktual\\", ylabel=\\"jumlah prediksi\\", title=\\"Prediksi vs aktual (validasi)\\"); ax[0].legend()\\n",\n    "ax[1].bar(by.index.astype(str), by[\\"porsi total error\\"], color=C2)\\n",\n    "pct_axis(ax[1], 0); ax[1].set(xlabel=\\"jumlah orang aktual\\", ylabel=\\"porsi total error absolut\\", title=\\"Dari mana MAE berasal?\\")\\n",\n    "save_fig(FIG_DIR, \\"07_error_breakdown\\")\\n",\n    "by.drop(columns=\\"total_error\\").style.format({\\"MAE\\": \\"{:.1f}\\", \\"MAE_regresi\\": \\"{:.1f}\\", \\"error_relatif\\": \\"{:.1%}\\", \\"porsi total error\\": \\"{:.0%}\\"})"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "9e8c17ad",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Error relatif CSRNet hampir sama di semua kelompok (13–18%), jadi model tidak gagal pada gambar tertentu; MAE besar di gambar padat hanyalah akibat jumlah orangnya besar. Gambar 201–1.000 orang menyumbang 51% total error absolut dan gambar di atas 1.000 orang 28%, padahal keduanya hanya 20% gambar validasi. Regresi langsung sebaliknya: error-nya membesar tajam pada gambar padat (MAE 2.343 untuk gambar di atas 1.000 orang)."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1cc768b5",\n   "metadata": {},\n   "source": [\n    "### 9.3 Apa yang dilihat model?"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "9916392a",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "va_df[\\"pred\\"] = p_fin\\n",\n    "va_df[\\"err\\"] = p_fin - yv\\n",\n    "show = [va_df.iloc[(va_df[\\"count\\"] - q).abs().argsort().iloc[0]] for q in [20, 150, 800]]\\n",\n    "show.append(va_df.loc[va_df.err.abs().idxmax()])\\n",\n    "fig, axes = plt.subplots(2, 4, figsize=(20, 8.5))\\n",\n    "for j, row in enumerate(show):\\n",\n    "    img, pts = resize_keep(Image.open(IMG_TR / row.img_id), row.points, MAX_SIDE)\\n",\n    "    axes[0, j].imshow(img); axes[0, j].scatter(pts[:, 0], pts[:, 1], s=3, c=C2); axes[0, j].axis(\\"off\\")\\n",\n    "    axes[0, j].set_title(f\\"{row.img_id}: aktual {row[\'count\']}\\" + (\\" (error terbesar)\\" if j == 3 else \\"\\"), fontsize=10)\\n",\n    "    axes[1, j].imshow(maps_va[row.img_id], cmap=\\"cividis\\"); axes[1, j].axis(\\"off\\")\\n",\n    "    axes[1, j].set_title(f\\"peta kepadatan prediksi: {row.pred:.0f}\\", fontsize=10)\\n",\n    "save_fig(FIG_DIR, \\"08_density_examples\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "4448b3fb",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Peta target menjumlahkan tepat ke jumlah orang dan mempertahankan lokasi setiap kepala. Kerumunan rapat menjadi pita terang yang padat, sedangkan orang yang tersebar menjadi titik-titik terpisah."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "9fcab9bf",\n   "metadata": {},\n   "source": [\n    "## 10. Submission\\n",\n    "\\n",\n    "Varian CSRNet dengan MAE validasi terendah dipakai untuk memprediksi 500 gambar uji (gambar utuh, resize sisi terpanjang 1024 px)."\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "bd97acbf",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "ds_te = CrowdDataset(DATA_DIR / \\"test\\" / \\"images\\", test_ids, None, train=False, max_side=MAX_SIDE)\\n",\n    "dl_te = DataLoader(ds_te, batch_size=1, shuffle=False, num_workers=2)\\n",\n    "ids_te, p_te, _, _ = predict_counts(csr, dl_te, DEVICE, \\"density\\", tta=\\"TTA\\" in FINAL_NAME)\\n",\n    "sub = sample[[\\"image_id\\"]].merge(pd.DataFrame({\\"image_id\\": ids_te, \\"predicted_count\\": p_te}), on=\\"image_id\\", how=\\"left\\")\\n",\n    "assert sub.predicted_count.notna().all() and len(sub) == len(sample)\\n",\n    "sub.to_csv(OUT_DIR / \\"submission.csv\\", index=False)\\n",\n    "res.to_csv(OUT_DIR / \\"validation_results.csv\\"); by.to_csv(OUT_DIR / \\"error_by_group.csv\\")\\n",\n    "pd.DataFrame(hist_csr).to_csv(OUT_DIR / \\"history_csrnet.csv\\", index=False); pd.DataFrame(hist_reg).to_csv(OUT_DIR / \\"history_regression.csv\\", index=False)\\n",\n    "fig, ax = plt.subplots(figsize=(9, 4))\\n",\n    "bins_ = np.logspace(0, np.log10(max(c.max(), p_te.max()) + 1), 35)\\n",\n    "ax.hist(c, bins=bins_, density=True, alpha=0.5, color=C1, label=\\"train (aktual)\\")\\n",\n    "ax.hist(np.maximum(p_te, 1), bins=bins_, density=True, alpha=0.5, color=C2, label=\\"test (prediksi)\\")\\n",\n    "ax.set(xscale=\\"log\\", xlabel=\\"jumlah orang\\", ylabel=\\"densitas\\", title=\\"Distribusi jumlah: train vs prediksi test\\"); ax.legend()\\n",\n    "save_fig(FIG_DIR, \\"09_test_distribution\\")\\n",\n    "print(f\\"Model: {FINAL_NAME} | prediksi test: median {np.median(p_te):.0f}, rata-rata {p_te.mean():.0f}, maks {p_te.max():.0f}\\")"\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "043f8262",\n   "metadata": {},\n   "source": [\n    "**Temuan.** Prediksi untuk 500 gambar uji: median 25, rata-rata 114, maksimum 1.737. Bentuk distribusinya mirip data latih (median 28, rata-rata 139), sehingga tidak ada tanda pergeseran besar antara data latih dan uji."\n   ]\n  },\n  {\n   "cell_type": "markdown",\n   "id": "1ad8c87e",\n   "metadata": {},\n   "source": [\n    "## 11. Kesimpulan\\n",\n    "\\n",\n    "1. **Label titik lebih berharga daripada label angka.** Dengan backbone yang sama (VGG16-BN), peta kepadatan mencapai MAE 24,9, sedangkan regresi jumlah langsung 139,4, bahkan lebih buruk daripada menebak median.\\n",\n    "2. **MAE ditentukan gambar padat.** 79% error berasal dari gambar berisi lebih dari 200 orang, padahal error relatifnya setara dengan gambar sepi.\\n",\n    "3. **Model meremehkan kerumunan terjauh.** Error terbesar muncul pada foto lapangan dengan ribuan kepala kecil di bagian atas (contoh: aktual 1.652, prediksi 988). Di sinilah resolusi input 1024 px membatasi model.\\n",\n    "4. **Hasil.** Late submission private 21,75, jauh di bawah submission tim saat kompetisi (39,44), tetapi masih di atas peringkat 1 (12,04). Model yang lebih baru (misalnya P2PNet atau DM-Count), resolusi input lebih tinggi, dan inferensi per potongan gambar adalah langkah berikutnya yang paling menjanjikan.\\n",\n    "\\n",\n    "**Keterbatasan.** Validasi hanya satu split 20% (380 gambar), sehingga MAE validasi berfluktuasi beberapa poin antar epoch. Skor late submission diperoleh setelah kompetisi berakhir dan tidak dapat dibandingkan secara setara dengan peserta yang bekerja dalam batas waktu kompetisi.\\n",\n    "\\n",\n    "### Jejak lingkungan"\n   ]\n  },\n  {\n   "cell_type": "code",\n   "execution_count": null,\n   "id": "4b4d5617",\n   "metadata": {},\n   "outputs": [],\n   "source": [\n    "import platform\\n",\n    "pkgs = [\\"numpy\\", \\"pandas\\", \\"torch\\", \\"torchvision\\", \\"matplotlib\\", \\"seaborn\\"]\\n",\n    "print(\\" | \\".join([f\\"python {platform.python_version()}\\"] + [f\\"{p} {version(p)}\\" for p in pkgs]))\\n",\n    "print(\\"GPU:\\", torch.cuda.get_device_name(0) if DEVICE.type == \\"cuda\\" else \\"tidak ada\\")\\n",\n    "print(f\\"Waktu eksekusi total: {(time.time() - T0) / 60:.1f} menit\\")"\n   ]\n  }\n ],\n "metadata": {\n  "accelerator": "GPU",\n  "kernelspec": {\n   "display_name": "Python 3",\n   "language": "python",\n   "name": "python3"\n  },\n  "language_info": {\n   "name": "python",\n   "version": "3.11"\n  }\n },\n "nbformat": 4,\n "nbformat_minor": 5\n}')

